def addp(text='',style=None,align=None,bold=False):
 p=doc.add_paragraph(style=(style.replace(' ','') if style and style.startswith('Heading ') else style))
 if text:
  r=p.add_run(text);r.bold=bold;r.font.name='Times New Roman';r.font.size=Pt(12);r._element.rPr.rFonts.set(qn('w:eastAsia'),'Times New Roman')
 p.paragraph_format.line_spacing=2;p.paragraph_format.space_after=Pt(0)
 if align is not None:p.alignment=align
 elif style not in ['Heading 1','Heading 2','Heading 3']:p.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
 return p
def pagebreak(): doc.add_page_break()
def heading(s,level=1): return addp(s,f'Heading {level}')
def add_table(headers,rows):
 t=doc.add_table(rows=1,cols=len(headers))
 for j,h in enumerate(headers):t.rows[0].cells[j].text=h
 for row in rows:
  cells=t.add_row().cells
  for j,v in enumerate(row):cells[j].text=str(v)
 for cell in t.rows[0].cells:
  for run in cell.paragraphs[0].runs: run.bold=True
 for row in t.rows:
  for cell in row.cells:
   for p in cell.paragraphs:
    p.paragraph_format.line_spacing=2;p.paragraph_format.space_after=Pt(0)
    for r in p.runs:r.font.name='Times New Roman';r.font.size=Pt(12)
 return t
